ROOT=Path(__file__).resolve().parents[1]; SITE=ROOT/'site'; BASE='https://getecoback.com/'
PAGES={
'wohnkosten-werkstatt':('Haushaltskosten prüfen: messen, trocknen, vergleichen','Drei kostenlose Rechner für Haushaltsstrom: Wäsche trocknen, Verbrauch messen und Gerätewechsel prüfen. Mit Rechenbeispielen und Messprotokoll.'),
'waeschetrockner-oder-luftentfeuchter':('Trockner oder Entfeuchter? Stromkosten vergleichen','Vergleiche Trockner und Luftentfeuchter mit eigenen Messwerten. Berechne Kosten pro Ladung und je Saison, auch wenn nur ein Teil der Wäsche wechselt.'),
'strommess-protokoll':('Stromverbrauch messen: Protokoll und Jahreskosten','Gemessene Kilowattstunden statt Typenschild-Watt: Verbrauch auf Betriebstage hochrechnen, Messprotokoll herunterladen und Stromfresser prüfen.'),
'geraete-austausch-rechner':('Altes Gerät behalten oder ersetzen? Kostenrechner','Berechne, wann geringere Stromkosten einen Gerätekauf ausgleichen. Mit Kaufpreis, eigenem Tarif, Jahresverbrauch und offenem Rechenweg.')}
LINKS=''.join(f'<a href="/{s}.html"><strong>{t}</strong><span>{d}</span></a>' for s,(t,d) in list(PAGES.items())[1:])
SOURCE_DRY='https://www.verbraucherzentrale.de/wissen/energie/strom-sparen/beim-kauf-eines-waeschetrockners-an-den-stromverbrauch-denken-37984'
SOURCE_AIR='https://www.verbraucherzentrale.de/wissen/energie/strom-sparen/heizen-und-lueften-so-gehts-richtig-10426'
PRINT_ENERGY_PANEL = '''<section class="work-panel" id="3d-drucker-stromverbrauch" aria-labelledby="3d-drucker-stromverbrauch-title">
<h2 id="3d-drucker-stromverbrauch-title">Wie viel Strom verbraucht ein 3D-Druck?</h2>
<p>Miss für einen Druck die <strong>gesamten kWh an der Steckdose</strong>: vor dem Aufheizen starten und bis zum Ende des Druckvorgangs messen. Der Wattwert beim Aufheizen verrät noch nicht, was das fertige Teil kostet.</p>
<ol>
<li>Notiere Drucker, Material, Temperaturen und Laufzeit. Vergleiche Drucke nur bei nachvollziehbaren Einstellungen.</li>
<li>Wenn du den Leerlauf mitrechnen willst, miss ihn getrennt. Bei sehr kleinen Lasten prüfe unten zuerst, was dein Messgerät tatsächlich auflösen kann.</li>
<li>Multipliziere die gemessenen kWh mit deinem Stromtarif. Rechne Material inklusive Stützen und Fehlversuchen separat dazu.</li>
</ol>
<p><strong>Beispiel, kein Gerätemesswert:</strong> 0,24 kWh × 0,35 €/kWh ergeben rund 0,08 € Strom. 55 g Filament inklusive Stützen kosten bei 20 €/kg weitere 1,10 €. Zusammen sind es rund 1,18 € vor Verschleiß und Anschaffung. Wenn du erst einen Drucker kaufen müsstest, vergleiche zusätzlich ein Angebot vom Druckdienst und ein verfügbares Fertigteil.</p>
<p><a href="/familienwerkstatt.html#repair">Für ein kleines, unbelastetes Projekt prüfen: kaufen, drucken oder erst ausmessen?</a> · <a href="#calculator">Verbrauch über einen ganzen Nutzungstag hochrechnen</a></p>
</section>'''
LOW_LOAD_PANEL = '''<section class="work-panel" aria-labelledby="kleine-lasten-messen">
<h2 id="kleine-lasten-messen">Kleine Standby-Lasten messen: Was bedeuten 0 W und 0,00 kWh?</h2>
<p><strong>Prüfe zuerst die untere Messgrenze des konkreten Geräts.</strong> 0 W ist eine momentane Leistungsanzeige. 0,00 kWh ist der abgelesene kumulierte Zählerstand. Wenn das Messgerät die kleine Last nicht zuverlässig erfasst, kann auch nach langer Zeit 0 stehen.</p>
<p><strong>Messdauer planen:</strong> Anzeigeschritt in kWh × gewünschte Schritte × 1.000 ÷ erwartete konstante Leistung in W. Bei 0,5 W und einem Anzeigeschritt von 0,01 kWh sind das rechnerisch 20 Stunden für einen Schritt und 60 Stunden für drei. Vorausgesetzt, das Messgerät erfasst 0,5 W und integriert durchgehend. Ein kleinerer Anzeigeschritt allein verspricht keine bessere Genauigkeit.</p>
<p><strong>Unveränderte Anzeige einordnen:</strong> Bleibt der kumulierte Zähler bei einem Schritt von 0,01 kWh fünf Stunden lang unverändert, liegt die erfasste mittlere Leistung rechnerisch unter etwa 2 W. Das setzt eine dokumentierte Erfassung dieser Last, eine durchlaufende Messung ohne Reset und das passende Anzeigeverhalten voraus. Zusätzlicher Messfehler ist in der Grenze nicht enthalten. Prüfe außerdem, ob die App einen Kalendertag oder ein rollendes Zeitfenster zeigt.</p>
<h3>Zwei Herstellerangaben richtig lesen</h3>
<ul>
<li><a href="https://www.brennenstuhl.com/de-DE/produkte/reise-steckdosenadapter/primera-line-energiemessgeraet-pm-231-e">Brennenstuhl PM 231 E, Artikel 1506600</a>: Der <a href="https://service.brennenstuhl.com/hc/de/articles/8867312023453">Hersteller-Service</a> nennt einen Leistungsbereich von 0,2 bis 3.600 W, eine Genauigkeit von ±1 % oder ±0,2 W sowie unter 0,5 W eigenen Verbrauch ohne benannten Betriebszustand. Der untere Bereichswert und der mögliche Fehler sind verschiedene Angaben.</li>
<li><a href="https://www.tp-link.com/de/home-networking/smart-plug/tapo-p110/v1%20%281-pack%29/">TP-Link Tapo P110 V1, deutsche Einzelpackung</a>: Die technischen Daten nennen für die Steckdose selbst 0,64 W bei geöffnetem Relais und 1,64 W als Maximalwert bei geschlossenem Relais. Eine Messuntergrenze für die angeschlossene Last gibt diese Produktseite nicht an. Aus dem Eigenverbrauch lässt sich die Messuntergrenze nicht ablesen.</li>
</ul>
<p><strong>Erst ausleihen, dann bei Bedarf auswählen:</strong> Frag deine örtliche Bibliothek nach einem Strommessgerät. Das <a href="https://www.umweltbundesamt.de/themen/klima-energie/energiesparen/energiesparen-im-haushalt/energiesparpaket-in-bibliotheken">Umweltbundesamt beschreibt den kostenlosen Verleih in teilnehmenden Bibliotheken</a>. Lass dir vorab Modell und Eignung für kleine Lasten bestätigen. Mit einem verlässlichen kWh-Messwert kannst du <a href="#calculator">oben die Kosten berechnen</a>.</p>
<p class="work-note">Herstellerangaben und Verleihhinweis am <time datetime="2026-11-26">26. November 2026</time> geprüft. Rechenbeispiele und veröffentlichte Spezifikationen, keine eigenen Gerätetests.</p>
</section>'''
def field(name,label,value,lo,hi,step='any'):
 return f'<label>{label}<input name="{name}" type="number" value="{value}" min="{lo}" max="{hi}" step="{step}" required inputmode="decimal"></label>'
def form(kind,fields,example,measurement_note=''):
 if kind=='drying': return laundry_block(False)
 return f'''<section class="work-panel" aria-labelledby="calculator"><h2 id="calculator">Mit deinen Werten rechnen</h2><p class="work-note">Die vorbelegten Zahlen sind frei gewählte Rechenbeispiele, keine Produktmessungen oder aktuellen Stromtarife. Ersetze sie durch deine Werte.</p>{measurement_note}<form data-household="{kind}"><div class="work-fields">{''.join(field(*f) for f in fields)}</div><button type="submit">Kosten berechnen</button></form><p id="result" role="status" tabindex="-1">{example}</p><p class="work-note">Eingaben werden lokal im Browser verarbeitet und nicht gespeichert oder als Messwerte übertragen. Ein Rechenaufruf wird ohne Eingabewerte gezählt.</p><noscript><p>Für eigene Berechnungen ist JavaScript nötig. Der Rechenweg und das Beispiel darunter funktionieren auch ohne JavaScript.</p></noscript></section>'''
def ad(terms):
 links=''.join(f'<a href="https://www.amazon.de/s?k={term}&amp;tag=getecoback-21" target="_blank" rel="sponsored noopener">{label} bei Amazon.de suchen</a>' for term,label in terms)
 us={'Luftentfeuchter+Hygrostat':'dehumidifier','Waermepumpentrockner':'heat+pump+dryer','Strommessgeraet+kWh':'electricity+usage+monitor'}
 links += '<p>In den USA einkaufen? Wähle die passende US-Kategorie:</p>' + ''.join(f'<a href="https://www.amazon.com/s?k={us[term]}&amp;tag=ecoback0d-20" target="_blank" rel="sponsored noopener">{label} bei Amazon.com suchen</a>' for term,label in terms)
 return f'<!--EB_HOUSEHOLD_AD--><aside class="work-ad"><p><strong>Anzeige · Affiliate-Links</strong></p><p>Als Amazon-Partner verdienen wir an qualifizierten Verkäufen. Für dich bleibt der Preis gleich. Suchergebnisse können variieren; wir haben die Geräte nicht selbst getestet. Prüfe das konkrete Modell und die Herstelleranleitung.</p>{links}</aside><!--/EB_HOUSEHOLD_AD-->'
def page(slug,lead,body,scheme):
 title,desc=PAGES[slug];url=BASE+slug+'.html'
 modified={'waeschetrockner-oder-luftentfeuchter':'2026-11-23','strommess-protokoll':'2026-11-27'}.get(slug,'2026-09-19')
 next_links=''.join(f'<a href="/{s}.html"><strong>{t}</strong><span>{d}</span></a>' for s,(t,d) in list(PAGES.items())[1:] if s!=slug)
 ld={'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':url,'inLanguage':'de','datePublished':'2026-09-19','dateModified':modified,'publisher':{'@type':'Organization','name':'EcoBack','url':BASE}}
 return f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | EcoBack</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{url}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="{url}"><link rel="stylesheet" href="/assets/household.css"><script type="application/ld+json">{json.dumps(ld,ensure_ascii=False)}</script><script type="module" src="/assets/household.mjs"></script></head><body class="eb-work"><main class="work-wrap" id="main"><a href="/tools.html">Alle EcoBack-Rechner</a><header class="work-intro"><div><p class="work-kicker">Die EcoBack Haushaltswerkstatt</p><h1>{title}</h1><p>{lead}</p><a class="work-button" href="{'#aufgaben' if slug=='wohnkosten-werkstatt' else '#laundry-check' if slug=='waeschetrockner-oder-luftentfeuchter' else '#calculator'}">{'Meine Aufgabe wählen' if slug=='wohnkosten-werkstatt' else 'Mit eigenen Werten rechnen'}</a><p class="work-note">EcoBack Redaktion · {'1. Oktober 2026' if slug=='waeschetrockner-oder-luftentfeuchter' else '19. September 2026'}</p></div><aside class="work-scheme">{scheme}</aside></header>{body}<h2>Dein nächster Schritt</h2><nav class="work-links" aria-label="Haushaltsrechner">{next_links}</nav><p><a href="/wohnkosten-werkstatt.html">Zur Haushaltswerkstatt</a> · <a href="/wie-wir-empfehlen.html">Wie wir empfehlen</a></p></main></body></html>'''
def main():
 body='''<h2>Eine Messung ist besser als ein Werbeversprechen.</h2><p>Ein kleineres Gerät ist nicht automatisch billiger im Betrieb: Entscheidend sind Verbrauch und Laufzeit für dieselbe Aufgabe. Hier trennst du die Messung, den Kostenvergleich und die Kaufentscheidung.</p><nav id="aufgaben" class="work-links" aria-label="Aufgabe wählen">'''+LINKS+'''</nav><h2>In drei Schritten zur Entscheidung</h2><ol class="work-steps"><li><strong>Gleiches mit Gleichem vergleichen.</strong> Beim Trocknen dieselbe Wäschemenge und Restfeuchte, beim Kühlschrank vergleichbare Größe und Umgebung.</li><li><strong>Eine vollständige Nutzung messen.</strong> Einschaltleistung in Watt ist kein Jahresverbrauch. Notiere Energie in kWh und Dauer.</li><li><strong>Erst rechnen, dann auswählen.</strong> Wenn der Stromvorteil den Kaufpreis nicht ausgleicht, ist Weiterverwenden oft die günstigere Kostenannahme.</li></ol><h2>Feuchtigkeit zuerst verstehen</h2><p>Wer drinnen Wäsche trocknet, verändert auch das Raumklima. Ein Stromkostenvergleich diagnostiziert keine Feuchteursache und berechnet keine Gebäudeschäden. Nutze dafür unsere vorhandenen Ratgeber:</p><ul><li><a href="/guide/waesche-trocknen-wohnung.html">Wäsche in der Wohnung trocknen</a></li><li><a href="/guide/luftfeuchtigkeit-senken.html">Luftfeuchtigkeit senken und Lüften einordnen</a></li><li><a href="/guide/luftentfeuchter-keller.html">Was bei einem feuchten Keller anders ist</a></li></ul><h2>Dein Messblatt</h2><p><a href="/downloads/haushalt-messprotokoll.csv" download>Leeres Messprotokoll als CSV herunterladen</a>. Keine Anmeldung. Fülle es in deiner Tabellenkalkulation aus oder drucke die Rechnerseite. Namen, Adressen und Zählernummern sind nicht nötig.</p><h2>Was diese Werkstatt nicht behauptet</h2><p>Wir haben keine eigenen Produkttests durchgeführt. Die Beispielzahlen sind keine Rangliste. Ergebnisse hängen von deinen Eingaben ab; Energiebedarf, Laufzeit und Tarife können sich ändern. Ein Rechnerergebnis ist keine Zusage einer Ersparnis.</p>'''
 (SITE/'wohnkosten-werkstatt.html').write_text(page('wohnkosten-werkstatt','Messen, vergleichen, erst dann kaufen. Finde heraus, welche Haushaltsentscheidung sich mit deinen eigenen Zahlen trägt.',body,'<p><strong>Messen</strong>kWh statt nur Watt</p><p><strong>Vergleichen</strong>Dieselbe Aufgabe, derselbe Tarif</p><p><strong>Entscheiden</strong>Kaufpreis und Nutzungsdauer mitdenken</p>'))
 body=form('drying',[('dryer','Trockner: kWh je Ladung',1.5,0,20),('watts','Entfeuchter: mittlere Leistung in Watt',250,0,5000),('hours','Entfeuchter: Stunden je Trocknung',6,0,72),('loads','Ladungen pro Woche',3,0,30),('price','Dein Strompreis in €/kWh',.35,0,5)],'Beispiel: 1,5 kWh im Trockner und 250 W × 6 h = 1,5 kWh im Entfeuchter kosten beide 0,525 € je Durchgang. Bei drei Ladungen pro Woche: je 81,90 € im Jahr.')+f'''<h2>So wird der Vergleich fair</h2><ol class="work-steps"><li>Nimm für beide Varianten gleich viel Wäsche aus demselben Schleuderprogramm. Vergleiche den gleichen gewünschten Trocknungsgrad.</li><li>Lies beim Trockner die kWh je Ladung ab. Den Labelwert eines separaten Trockners in kWh je 100 Zyklen teilst du durch 100. Bei einem <a href="#waschtrockner-label">Waschtrockner gelten andere Labelwerte</a>. Ein tatsächlicher Messwert passt besser zu deinem Programm als ein abweichender Prüfzyklus.</li><li>Miss beim Entfeuchter die gesamte Energie bis zum gleichen Trocknungsgrad. Im Rechner kannst du die gemessenen kWh direkt eingeben. Typenschild-Watt allein kann den Vergleich verzerren.</li></ol><h2>Der Rechenweg</h2><p>Entfeuchter: Watt × Stunden ÷ 1.000. Kosten je Ladung: kWh × €/kWh. Wenn du nur einen Luftentfeuchter nutzt, kannst du <a href="#luftentfeuchter-waesche-kosten">den Strom für einen einzelnen Trocknungsgang berechnen</a>. Jahreskosten: Kosten je Ladung × Ladungen je Woche × 52. Reine Wäscheleine ohne elektrisches Gerät hat keine direkten Gerätestromkosten; zusätzliche Heiz- und Lüftungsenergie ist damit nicht erfasst.</p><h2>Was das Ergebnis nicht abdeckt</h2><p>Ein Entfeuchter kann auch Feuchte aus dem Raum aufnehmen. Wie viel davon aus der Wäsche stammt, weiß der Rechner nicht. Unterschiedliche Restfeuchte, Raumerwärmung, Anschaffung, Platzbedarf und deine Zeit fehlen im Kostenwert. Deshalb gibt es hier keinen pauschalen Sieger.</p><h2>Nach dem Rechnen</h2><p>Wenn du bereits einen Trockner besitzt, ist dessen Kaufpreis für diese einzelne Nutzung nicht erneut fällig. Wenn du erst kaufen müsstest, nutze zusätzlich den <a href="/geraete-austausch-rechner.html">Kaufpreisvergleich</a>. Für die Praxis: <a href="/guide/waesche-trocknen-wohnung.html">Wäsche in der Wohnung</a> und <a href="/guide/luftentfeuchter-ratgeber.html">Entfeuchter-Auswahlkriterien</a>.</p><h2>Quellen und Grenzen</h2><p>Die <a href="{SOURCE_DRY}">Verbraucherzentrale erklärt das Trockner-Energielabel</a>, einschließlich kWh je 100 Trocknungen. Unsere Szenariorechnung ist keine Prüfung eines bestimmten Geräts. <a href="{SOURCE_AIR}">Hinweise zu Heizen und Lüften</a> helfen, Raumfeuchte getrennt von den Stromkosten zu betrachten.</p>'''+ad([('Luftentfeuchter+Hygrostat','Entfeuchter mit Hygrostat'),('Waermepumpentrockner','Wärmepumpentrockner')])
 (SITE/'waeschetrockner-oder-luftentfeuchter.html').write_text(page('waeschetrockner-oder-luftentfeuchter','Nicht Watt allein entscheidet. Vergleiche den Strom für eine gleich trockene Wäscheladung und sieh, was deine Nutzung im Jahr kostet.',body,'<p><strong>Gleiche Wäsche</strong>Menge und Restfeuchte angleichen</p><p><strong>Ganzer Durchgang</strong>kWh und Laufzeit messen</p><p><strong>Offener Vergleich</strong>Kein pauschaler Testsieger</p>'))
 body=form('measured',[('kwh','Gemessene Energie in kWh',1.2,0,10000),('hours','Messdauer in Stunden',48,.01,8760),('days','Betriebstage pro Jahr',365,0,366),('price','Dein Strompreis in €/kWh',.35,0,5)],'Beispiel: 1,2 kWh in 48 Stunden = 0,6 kWh pro Tag. Bei 365 vergleichbaren Betriebstagen: 219 kWh und 76,65 € im Jahr.',
           measurement_note='<p class="work-note">Noch kein kWh-Messwert? Prüfe <a href="#kleine-lasten-messen">Messbereich und Anzeigeauflösung</a> deines Steckdosenmessgeräts. Für die Messung per App kannst du auf unserer Schwesterseite The Doll Scout <a data-meter-referral href="https://thedollscout.com/de/shop/categories/smart-home#strommessung">Messsteckdosen mit und ohne Matter vergleichen</a>.</p><script type="module" src="/assets/meter-referral.mjs?v=d1df51ac6dd0"></script>')+PRINT_ENERGY_PANEL+LOW_LOAD_PANEL+'''<h2>Ein Messplan für drei verschiedene Geräte</h2><div class="work-table"><table><thead><tr><th>Gerät</th><th>Was du misst</th><th>Warum die Momentaufnahme täuscht</th></tr></thead><tbody><tr><td>Kühlschrank</td><td>Mehrere vollständige Tage im üblichen Alltag</td><td>Der Kompressor läuft nicht durchgehend; Türöffnungen und Raumtemperatur verändern den Verbrauch.</td></tr><tr><td>Entfeuchter</td><td>Einen typischen Betriebstag bei notierter Feuchte und Zielvorgabe</td><td>Hygrostat und wechselnde Feuchtelast verändern die Laufzeit.</td></tr><tr><td>Trockner</td><td>Einen vollständigen Durchgang einschließlich Abkühlphase</td><td>Einzelne Lastspitzen sagen wenig über die Energie je Wäscheladung.</td></tr></tbody></table></div><h2>So füllst du das Protokoll aus</h2><ol class="work-steps"><li>Notiere Gerät, Datum und normalen Einsatz. Keine Seriennummer oder Adresse erforderlich.</li><li>Nutze nur ein für den Anschluss und die Last geeignetes Messgerät gemäß Herstelleranleitung. Keine Arbeiten an offenen Leitungen oder fest angeschlossenen Geräten.</li><li>Lies die Differenz des kWh-Zählers und die verstrichene Zeit ab. Wiederhole bei ungewöhnlicher Nutzung oder anderen Jahreszeiten.</li><li>Trage oben deine realistischen Betriebstage ein. Bei Geräten mit einzelnen Zyklen ist ein Vergleich pro vollständiger Nutzung sinnvoller als eine 24-Stunden-Hochrechnung.</li></ol><p><a href="/downloads/haushalt-messprotokoll.csv" download>Messprotokoll herunterladen</a></p><h2>Formel und Unsicherheit</h2><p>kWh je 24 Stunden = gemessene kWh ÷ Messstunden × 24. Jahreskosten = Tagesverbrauch × Betriebstage × Strompreis. Kurze Messungen, ein leerer Kühlschrank oder ungewöhnliche Außentemperaturen ergeben keine belastbare Jahresprognose. Der Rechner verlängert nur deinen beobachteten Durchschnitt.</p><h2>Wann lohnt sich ein neues Gerät?</h2><p>Ein hoher Verbrauch ist ein Anlass zum Prüfen, kein automatischer Kaufgrund. Erst Nutzung und Wartung ansehen, dann beim <a href="/geraete-austausch-rechner.html">Austauschrechner</a> Anschaffung und Stromkosten gemeinsam rechnen. Weitere Maßnahmen: <a href="/guide/strom-sparen-haushalt.html">Strom sparen im Haushalt</a>.</p>'''+ad([('Strommessgeraet+kWh','Strommessgerät mit kWh-Anzeige')])
 (SITE/'strommess-protokoll.html').write_text(page('strommess-protokoll','Finde große Verbraucher mit einer nachvollziehbaren Messung. Rechne deinen beobachteten Verbrauch hoch und halte die Annahmen fest.',body,'<p><strong>Energie</strong>1,2 kWh im Beispiel</p><p><strong>Zeit</strong>48 Stunden gemessen</p><p><strong>Vergleichswert</strong>0,6 kWh je 24 Stunden</p>'))
 body=form('replacement',[('oldKwh','Vorhandenes Gerät: kWh pro Jahr',400,0,20000),('newKwh','Neues Gerät: kWh pro Jahr',200,0,20000),('price','Dein Strompreis in €/kWh',.35,0,5),('purchase','Gesamter Kaufpreis einschließlich Lieferung in €',500,0,50000),('years','Vergleichszeitraum in Jahren',5,1,30,'1')],'Beispiel: 200 kWh weniger × 0,35 € = 70 € Stromersparnis pro Jahr. 500 € Kaufpreis ÷ 70 € = rund 7,14 Jahre. Nach fünf Jahren kostet Behalten 700 €, Neukauf einschließlich Strom 850 €.')+'''<h2>Behalten ist der richtige Vergleichspunkt</h2><p>Der frühere Kaufpreis des vorhandenen Geräts ist bereits bezahlt. Für die heutige Entscheidung vergleichst du seine künftigen Kosten mit dem Kauf und Betrieb des neuen Geräts. Ist das alte Gerät defekt oder erfüllt es die Aufgabe nicht mehr, beantwortet diese reine Stromrechnung die Entscheidung nicht vollständig.</p><h2>Gleiche Leistung, gleiche Grundlage</h2><p>Vergleiche ähnliche Gerätegröße und Nutzungsmenge. Ein kleineres Gerät mit weniger Funktionen löst möglicherweise eine andere Aufgabe. Setze bei beiden Geräten dieselbe Anzahl von Zyklen an. Bei Labelangaben je 100 Zyklen: Wert ÷ 100 × deine Zyklen pro Jahr. Mischt du alte Jahreslabel und neue Zykluslabel ungeprüft, entsteht ein falscher Vorteil.</p><h2>Formel</h2><p>Jährliche Stromersparnis = (alter Jahresverbrauch − neuer Jahresverbrauch) × Strompreis. Einfache Rückflusszeit = Kaufpreis ÷ positive jährliche Stromersparnis. Bei null oder negativem Vorteil gibt es durch Strom allein keine Rückflusszeit. Über den gewählten Zeitraum addiert der Rechner Stromkosten und neuen Kaufpreis.</p><h2>Was fehlt?</h2><p>Wartung, mögliche Reparaturen, Wiederverkaufswert, Finanzierung, künftige Tarifänderungen und die Umweltwirkungen der Herstellung fehlen. Auch die verbleibende Lebensdauer ist unbekannt. Eine Rückflusszeit von 15 Jahren bedeutet nicht, dass das neue Gerät so lange funktioniert.</p><h2>Vor dem Kauf</h2><ol class="work-steps"><li><a href="/strommess-protokoll.html">Vorhandenen Verbrauch messen</a>, statt nur einen hohen Typenschildwert zu übernehmen.</li><li>Für das konkrete neue Modell Herstellerdaten oder den Datensatz in <a href="https://eprel.ec.europa.eu/">EPREL</a> prüfen. Kein beliebiges Modell aus derselben Produktfamilie einsetzen.</li><li>Mindestens zwei realistische Szenarien rechnen: deine heutige Nutzung und eine niedrigere Nutzung. Einen höheren Strompreis nicht als sicher voraussetzen.</li></ol><p>Für zwei Trocknungsverfahren statt zweier Geräte: <a href="/waeschetrockner-oder-luftentfeuchter.html">Wäschekosten vergleichen</a>.</p>'''
 (SITE/'geraete-austausch-rechner.html').write_text(page('geraete-austausch-rechner','Ein sparsameres Gerät spart Strom. Ob es auch Geld spart, entscheidet sich erst mit Kaufpreis und Nutzungsdauer.',body,'<p><strong>Vorhanden</strong>Künftige Stromkosten</p><p><strong>Neu</strong>Kaufpreis plus Stromkosten</p><p><strong>Entscheidung</strong>Beide über denselben Zeitraum</p>'))
